effect.shader:
const float GIRO = 1.0;          // o sentido do Rotate Colors (medido)

const float LARGURA_MAX = 720.0;     // a maior largura do desfoque, em px do buffer

// ---- a camada do AE no buffer --------------------------------------------------------------
ivec2 gT;          // o buffer
ivec2 gN;          // a camada do AE dentro dele, em px
ivec2 gInicio;     // o canto da camada no buffer
float gEscala;     // a prévia reduzida (Blur Matte é em px da composição)
bool gDePe;        // cena de pé (camada de ajuste, grupo solto): a linha 0 do buffer é a base da imagem

void preparar() {
    gT = textureSize(inputImg, 0);
    gN = clamp(ivec2(floor(max(acCamada, vec2(0.001)) * vec2(gT) + 0.5)), ivec2(1), gT);
    gInicio = (gT - gN) / 2;
    gEscala = acEscalaDePixel > 0.0 ? acEscalaDePixel : 1.0;
    gDePe = acEntradaDePe == 1;
}

/** Espelha o índice na camada repetindo o pixel da borda (abc|cba), quantas voltas forem. */
int espelhar(int i, int n) {
    if (i >= 0 && i < n) return i;
    int p = 2 * n;
    i = i - (i / p) * p; if (i < 0) i += p;
    return i < n ? i : p - 1 - i;
}

ivec2 naCamada(ivec2 q) {
    return gInicio + ivec2(espelhar(q.x, gN.x), espelhar(q.y, gN.y));
}

// ---- o núcleo das três caixas (o do S_Hotspots e do S_HalfTone) -------------------------------
// Largura inteira n -> raios r0 ≥ r1 ≥ r2 que somam n ((n + 2 − i) div 3); a soma das três caixas em d, em
// inteiros (exata), dividida no fim por (2r0 + 1)(2r1 + 1)(2r2 + 1).
int somaDoTrapezio(int x, int p, int q) {
    int m = q - p;
    int M = p + q;
    x = min(x, M);
    if (x <= m) return (x + 1) * (2 * p + 1);
    return (m + 1) * (2 * p + 1) + (x - m) * (M + 1) - (x * (x + 1) - m * (m + 1)) / 2;
}

int acumulado(int x, int p, int q) {
    int total = (2 * p + 1) * (2 * q + 1);
    int meio = (total - (2 * p + 1)) / 2;
    if (x >= 0) return meio + somaDoTrapezio(x, p, q);
    return total - (meio + somaDoTrapezio(-x - 1, p, q));
}

float pesoDasCaixas(int d, int n) {
    if (n <= 0) return d == 0 ? 1.0 : 0.0;
    int r0 = (n + 2) / 3;
    int r1 = (n + 1) / 3;
    int r2 = n / 3;
    if (abs(d) > n) return 0.0;
    int c = acumulado(d + r0, r2, r1) - acumulado(d - r0 - 1, r2, r1);
    return float(c) / (float(2 * r0 + 1) * float(2 * r1 + 1) * float(2 * r2 + 1));
}

// Um valor de 0..1 em 24 bits num texel RGBA8.
vec4 gravar24(float m) {
    float a = floor(clamp(m, 0.0, 1.0) * 16777215.0 + 0.5);
    float b0 = floor(a / 65536.0);
    float r = a - b0 * 65536.0;
    float b1 = floor(r / 256.0);
    return vec4(b0, b1, r - b1 * 256.0, 255.0) / 255.0;
}

float ler24(vec4 v) {
    vec3 b = floor(v.rgb * 255.0 + 0.5);
    return (b.x * 65536.0 + b.y * 256.0 + b.z) / 16777215.0;
}

// ---- a máscara (PROCESS_MASKS: a mesma do S_HalfTone e do S_Emboss) ---------------------------
bool temMascara() { return textureSize(maskImg, 0).x > 1; }

float mascara(ivec2 p) {
    vec4 m = texture(maskImg, (vec2(p) + 0.5) / vec2(gT));
    float v = maskUse == 1 ? m.a : dot(m.rgb * m.a, vec3(0.3125, 0.5, 0.1875));
    return invertMask ? 1.0 - v : v;
}

// o blur da máscara é sem subpixel (a largura arredonda)
int larguraDaMascara() { return int(clamp(floor(blurMask * gEscala + 0.5), 0.0, LARGURA_MAX)); }

float mascaraDesfocadaX(ivec2 q) {
    int n = larguraDaMascara();
    float soma = 0.0;
    for (int d = -n; d <= n; d++) {
        float k = pesoDasCaixas(d, n);
        if (k != 0.0) soma += k * mascara(naCamada(q + ivec2(d, 0)));
    }
    return soma;
}

float mascaraDesfocadaY(ivec2 q) {
    int n = larguraDaMascara();
    float soma = 0.0;
    for (int d = -n; d <= n; d++) {
        float k = pesoDasCaixas(d, n);
        if (k != 0.0) soma += k * ler24(texelFetch(mH, naCamada(q + ivec2(0, d)), 0));
    }
    return soma;
}

/** A máscara no pixel p do buffer (1 sem camada de máscara). */
float mascaraEm(ivec2 p) {
    if (!temMascara()) return 1.0;
    return larguraDaMascara() > 0 ? ler24(texelFetch(mV, p, 0)) : mascara(p);
}

// ---- a luminância ----------------------------------------------------------------------------
// Medido: Normal (1) faz a conta na cor pré-multiplicada; All Opaque (0) e As Premult (2), na cor reta.
vec3 corDaFonte(vec4 s) { return opacity == 1 ? s.rgb * s.a : s.rgb; }

/** monochrome (0x180f26020) da camada. */
float luma(ivec2 p) {
    vec3 c = corDaFonte(texelFetch(inputImg, p, 0));
    return (0.3125 * c.r + 0.5 * c.g) + 0.1875 * c.b;
}

/** O edge_smooth da definição: o Edge Smooth do AE chega em px da composição e vira px / (W / 8). */
float suaveInterno() { return edgeSmooth * gEscala * 8.0 / float(gN.x); }

/** A largura do blur: 0,125 · W · edge_smooth, em px do buffer (= o Edge Smooth em px, na escala da prévia). */
float larguraDoBlur() {
    float w = clamp(0.125 * float(gN.x) * suaveInterno(), 0.0, LARGURA_MAX);
    return subpixelSmooth ? w : floor(w + 0.5);
}

/** Subpixel: a largura a + f mistura os núcleos de a e a + 1 (a conta do S_GlowAura). */
float pesoDoBlur(int d, float w) {
    int a = int(floor(w));
    float f = w - float(a);
    float k = pesoDasCaixas(d, a);
    return f > 0.0 ? k + (pesoDasCaixas(d, a + 1) - k) * f : k;
}

float lumaDesfocadaX(ivec2 q) {
    float w = larguraDoBlur();
    int n = int(ceil(w));
    float soma = 0.0;
    for (int d = -n; d <= n; d++) {
        float k = pesoDoBlur(d, w);
        if (k != 0.0) soma += k * luma(naCamada(q + ivec2(d, 0)));
    }
    return soma;
}

float lumaDesfocadaY(ivec2 q) {
    float w = larguraDoBlur();
    int n = int(ceil(w));
    float soma = 0.0;
    for (int d = -n; d <= n; d++) {
        float k = pesoDoBlur(d, w);
        if (k != 0.0) soma += k * ler24(texelFetch(bX, naCamada(q + ivec2(0, d)), 0));
    }
    return soma;
}

/** p na coluna x e na linha (da IMAGEM: 0 é o topo) da camada. */
float altura(int x, int linha) {
    int y = gDePe ? gN.y - 1 - linha : linha;
    ivec2 p = gInicio + ivec2(x, y);
    return larguraDoBlur() > 0.0 ? ler24(texelFetch(bY, p, 0)) : luma(p);
}

// ---- o grad (o do S_DistortChroma e do S_Emboss) ----------------------------------------------
/** Diferença central sem dividir por 2; na borda, um lado só vezes 2; y = a linha de cima menos a de baixo. */
vec2 gradiente(ivec2 q) {
    int x = q.x;
    int linha = gDePe ? gN.y - 1 - q.y : q.y;
    float gx, gy;
    if (gN.x < 2) gx = 0.0;
    else if (x == 0) gx = (altura(1, linha) - altura(0, linha)) * 2.0;
    else if (x == gN.x - 1) gx = (altura(x, linha) - altura(x - 1, linha)) * 2.0;
    else gx = altura(x + 1, linha) - altura(x - 1, linha);
    if (gN.y < 2) gy = 0.0;
    else if (linha == 0) gy = (altura(x, 0) - altura(x, 1)) * 2.0;
    else if (linha == gN.y - 1) gy = (altura(x, linha - 1) - altura(x, linha)) * 2.0;
    else gy = altura(x, linha - 1) - altura(x, linha + 1);
    return vec2(gx, gy);
}

vec3 cor8(vec4 c) { return floor(c.rgb * 255.0 + 0.5) / 255.0; }

void main() {
    preparar();
    ivec2 t = min(ivec2(floor(acScreenNorm * vec2(gT))), gT - ivec2(1));
    ivec2 q = t - gInicio;
    bool fora = any(lessThan(q, ivec2(0))) || any(greaterThanEqual(q, gN));

    if (acPass == 0) { fragColor = (fora || !temMascara()) ? vec4(0.0) : gravar24(mascaraDesfocadaX(q)); return; }
    if (acPass == 1) { fragColor = (fora || !temMascara()) ? vec4(0.0) : gravar24(mascaraDesfocadaY(q)); return; }
    if (acPass == 2) { fragColor = fora ? vec4(0.0) : gravar24(lumaDesfocadaX(q)); return; }
    if (acPass == 3) { fragColor = fora ? vec4(0.0) : gravar24(lumaDesfocadaY(q)); return; }

    // ---- 4: o gradiente e as cores ----
    vec4 s = texelFetch(inputImg, t, 0);
    if (fora) { fragColor = s; return; }

    vec2 g = gradiente(q) * (0.05 * float(gN.x) * brightness * (suaveInterno() + 0.1));
    float ang = radians(GIRO * rotateColors);
    float c = cos(ang), sn = sin(ang);
    g = vec2(g.x * c - g.y * sn, g.x * sn + g.y * c);
    // Medido: as cores valem em 8 bits.
    vec3 fundo = cor8(background);
    vec3 cx = g.x > 0.0 ? cor8(left) : cor8(right);
    vec3 cy = g.y > 0.0 ? cor8(bottom) : cor8(top);
    vec3 cor = fundo + (cx - fundo) * abs(g.x) + (cy - fundo) * abs(g.y);

    // Medido: a máscara mistura ANTES de prender (o dissolve do Autogen roda no efeito; o Opacity, depois, no AE),
    // com a Fonte na cor do Opacity (pré-multiplicada no Normal, reta nos outros dois).
    if (temMascara()) cor = mix(corDaFonte(s), cor, mascaraEm(t));

    // Opacity: Normal toma o resultado como JÁ pré-multiplicado, limitado ao alfa; As Premult, como cor reta com o alfa
    // da fonte; All Opaque sai opaco.
    float a;
    vec3 r;
    if (opacity == 0) { a = 1.0; r = clamp(cor, 0.0, 1.0); }
    else if (opacity == 1) { a = s.a; r = clamp(cor, vec3(0.0), vec3(a)); }
    else { a = s.a; r = clamp(cor, 0.0, 1.0) * a; }

    vec3 reta = a > 0.0 ? min(r / a, vec3(1.0)) : vec3(0.0);
    // a saída em níveis inteiros, arredondada como o AE de 8 bpc (a da GPU não arredonda igual)
    fragColor = vec4(floor(reta * 255.0 + 0.5) / 255.0, a);
}
